CREATE OR REPLACE FUNCTION public.inbox_favorite_target_access(_workspace uuid,_kind text,_target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT ws_current_access(_workspace) AND CASE _kind WHEN 'lead' THEN EXISTS (SELECT 1 FROM leads l WHERE l.id=_target AND l.workspace_owner_id=_workspace) WHEN 'message' THEN EXISTS (SELECT 1 FROM messages m LEFT JOIN leads l ON l.id=m.lead_id WHERE m.id=_target AND (l.workspace_owner_id=_workspace OR (m.lead_id IS NULL AND public.is_admin_or_above(auth.uid()) AND m.platform='whatsapp' AND m.direction='inbound' AND m.metadata->>'sender_phone' IS NOT NULL))) WHEN 'peer' THEN (public.is_community_chat_member(auth.uid()) AND _target<>auth.uid() AND public.is_community_chat_member(_target)) OR EXISTS (SELECT 1 FROM community_chat_messages c WHERE (c.sender_id=auth.uid() AND c.recipient_id=_target) OR (c.recipient_id=auth.uid() AND c.sender_id=_target)) WHEN 'peer_message' THEN EXISTS (SELECT 1 FROM community_chat_messages c WHERE c.id=_target AND (c.sender_id=auth.uid() OR c.recipient_id=auth.uid())) ELSE false END $$;
REVOKE ALL ON FUNCTION public.inbox_favorite_target_access(uuid,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.inbox_favorite_target_access(uuid,text,uuid) TO authenticated,service_role;